/** Verification checks per working shift. */
export const VERIFICATIONS_PER_SHIFT = 3

/* --------------------------------------------------------------------------
 * Seeded randomness — mock records must be stable across re-renders and
 * reloads, but varied across employees and days.
 * ------------------------------------------------------------------------ */

function hashString(str) {
  let h = 2166136261
  for (let i = 0; i < str.length; i += 1) {
    h ^= str.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

function mulberry32(seed) {
  let a = seed >>> 0
  return function next() {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function rngFor(...parts) {
  return mulberry32(hashString(parts.join(':')))
}

