/* --------------------------------------------------------------------------
 * Persistence helpers (only assignments and alert reviews mutate)
 * ------------------------------------------------------------------------ */

function readJson(key, fallback) {
  try {
    return JSON.parse(window.localStorage.getItem(key)) ?? fallback
  } catch {
    return fallback
  }
}

function writeJson(key, value) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value))
  } catch {
    // Ignore — mock persistence only.
  }
}

/* --------------------------------------------------------------------------
 * Reference lookups
 * ------------------------------------------------------------------------ */

/**
 * Working hours for a representative. Every worker follows the company's
 * standard working hours (Settings → Working Hours, 08:00–17:00 by default);
 * there are no shifts. Shaped for monitoring: label, working-day text and the
 * window in minutes since midnight.
 */
export function workHoursFor(rep, dateKey) {
  const h = defaultHoursFor(rep.companyId, dateKey)
  const { start, end } = shiftWindowMinutes(h)
  return {
    label: 'Standard hours',
    startTime: h.startTime,
    endTime: h.endTime,
    startMinutes: start,
    endMinutes: end,
    workingDays: formatWorkingDays(h.workingDays),
    workingDayList: h.workingDays,
  }
}

/**
 * The representative's official workplace: the active shop assignment saved at
 * registration (or the latest HR reassignment). Falls back to the rep's seed
 * shop for the demo's pre-existing records.
 */
function resolveShopId(rep) {
  const assignment = mockGetActiveAssignment(rep.employeeId)
  // An assignment to a shop that no longer exists (e.g. an old branch record)
  // falls back to the rep's demo shop.
  return assignment?.shopId && mockGetShop(assignment.shopId) ? assignment.shopId : rep.assignedShopId
}

/** Merchandisers (demo) with their active shop assignment applied. */
export function mockListSalesReps(companyId) {
  return SALES_REPS.filter((r) => r.companyId === companyId).map((r) => ({
    ...r,
    assignedShopId: resolveShopId(r),
  }))
}

/**
 * Everyone who works from a shop in a company: the demo's monitored reps plus
 * Merchandisers registered through the app. Used for
 * the Assigned Shops view. Registered staff have no simulated SMS history
 * (noSmsData), so nothing is invented for them.
 */
export function mockListFieldStaff(companyId) {
  const reps = mockListSalesReps(companyId)
  const ids = new Set(reps.map((r) => r.employeeId))
  const registered = mockListEmployees()
    .filter((e) => e.companyId === companyId && requiresShop(e.position) && !ids.has(e.staffId))
    .map((e) => ({
      employeeId: e.staffId,
      companyId: e.companyId,
      fullName: e.fullName,
      phoneNumber: e.phone || '—',
      position: e.position,
      employmentStatus: e.status,
      assignedShopId: mockGetActiveAssignment(e.staffId)?.shopId ?? e.assignedShopId ?? null,
      profileImage: e.faceImage ?? null,
      noSmsData: true,
    }))
  return [...reps, ...registered]
}

export function mockGetSalesRep(employeeId) {
  const rep = SALES_REPS.find((r) => r.employeeId === employeeId)
  if (!rep) return null
  return { ...rep, assignedShopId: resolveShopId(rep) }
}

/* --------------------------------------------------------------------------
 * Verification events — HISTORICAL ONLY
 *
 * The official schedule is generated by the backend and is never visible.
 * This mock fabricates only events whose dispatch time is in the past for
 * the selected date. Nothing upcoming is ever produced.
 * ------------------------------------------------------------------------ */

function minutesToIso(dateKey, minutes) {
  const [y, m, d] = dateKey.split('-').map(Number)
  const date = new Date(y, m - 1, d, 0, 0, 0, 0)
  date.setMinutes(minutes)
  return date.toISOString()
}

function generateDayEvents(rep, dateKey, now) {
  const shift = workHoursFor(rep, dateKey)
  const shop = mockGetShop(rep.assignedShopId)
  const rng = rngFor('events', rep.employeeId, dateKey)

  // Three unpredictable dispatch times inside the shift window, sorted.
  const startMin = shift.startMinutes
  const endMin = shift.endMinutes
  const span = endMin - startMin
  const segment = span / VERIFICATIONS_PER_SHIFT
  const dispatchMinutes = []
  for (let i = 0; i < VERIFICATIONS_PER_SHIFT; i += 1) {
    const offset = Math.floor(rng() * (segment - 20)) + 10
    dispatchMinutes.push(Math.floor(startMin + i * segment + offset))
  }
  dispatchMinutes.sort((a, b) => a - b)

  const isToday = dateKey === todayKey(now)
  const events = []

  dispatchMinutes.forEach((minute, index) => {
    const dispatchedAt = minutesToIso(dateKey, minute)
    // STRICT: never produce an event whose dispatch time is in the future.
    if (isToday && new Date(dispatchedAt).getTime() >= now.getTime()) return

    const eventRng = rngFor('event', rep.employeeId, dateKey, index)
    const verificationNumber = index + 1

    // SMS delivery
    const delivered = eventRng() < 0.93
    if (!delivered) {
      events.push({
        eventId: `${rep.employeeId}-${dateKey}-v${verificationNumber}`,
        employeeId: rep.employeeId,
        verificationNumber,
        dispatchedAt,
        deliveryStatus: 'failed',
        respondedAt: null,
        faceVerificationStatus: 'pending',
        livenessStatus: 'pending',
        gpsVerificationStatus: 'unavailable',
        distanceFromShop: null,
        gpsAccuracy: null,
        result: 'sms-failed',
      })
      return
    }

    // Employee response
    const responded = eventRng() < 0.88
    if (!responded) {
      events.push({
        eventId: `${rep.employeeId}-${dateKey}-v${verificationNumber}`,
        employeeId: rep.employeeId,
        verificationNumber,
        dispatchedAt,
        deliveryStatus: 'delivered',
        respondedAt: null,
        faceVerificationStatus: 'pending',
        livenessStatus: 'pending',
        gpsVerificationStatus: 'pending',
        distanceFromShop: null,
        gpsAccuracy: null,
        result: 'missed',
      })
      return
    }

    const respondedAt = minutesToIso(dateKey, minute + Math.floor(eventRng() * 5) + 1)

    // Face + liveness
    const facePassed = eventRng() < 0.9
    const livenessPassed = facePassed ? eventRng() < 0.97 : false

    // GPS
    const gpsRoll = eventRng()
    let gpsVerificationStatus
    let distanceFromShop
    let gpsAccuracy
    if (gpsRoll < 0.8) {
      gpsVerificationStatus = 'passed'
      distanceFromShop = Math.floor(eventRng() * (shop.geofenceRadius - 20)) + 5
      gpsAccuracy = Math.floor(eventRng() * 20) + 5
    } else if (gpsRoll < 0.92) {
      gpsVerificationStatus = 'failed'
      distanceFromShop = Math.floor(eventRng() * 600) + shop.geofenceRadius + 15
      gpsAccuracy = Math.floor(eventRng() * 25) + 8
    } else {
      gpsVerificationStatus = 'unavailable'
      distanceFromShop = null
      gpsAccuracy = null
    }

    let result
    if (!facePassed || !livenessPassed) result = 'failed-face'
    else if (gpsVerificationStatus === 'unavailable') result = 'gps-unavailable'
    else if (gpsVerificationStatus === 'failed') result = 'outside-shop'
    else result = 'verified'

    events.push({
      eventId: `${rep.employeeId}-${dateKey}-v${verificationNumber}`,
      employeeId: rep.employeeId,
      verificationNumber,
      dispatchedAt,
      deliveryStatus: 'delivered',
      respondedAt,
      faceVerificationStatus: facePassed ? 'passed' : 'failed',
      livenessStatus: livenessPassed ? 'passed' : 'failed',
      gpsVerificationStatus,
      distanceFromShop,
      gpsAccuracy,
      result,
    })
  })

  return events
}

/* --------------------------------------------------------------------------
 * Day state — attendance + verification for one rep on one date
 * ------------------------------------------------------------------------ */

/**
 * A day with no scheduled work for the rep: a rest day / public holiday
 * (outside the shift's working days) or approved leave. No check-in and no
 * verification events are produced, and no alerts are raised.
 */
function unscheduledDayState(rep, dateKey, status, leave) {
  return {
    rep,
    date: dateKey,
    checkedIn: false,
    checkInTime: null,
    checkOutTime: null,
    events: [],
    completedCount: 0,
    missedCount: 0,
    failedCount: 0,
    progress: `0/${VERIFICATIONS_PER_SHIFT}`,
    status,
    leave: leave ?? null,
    lastVerification: null,
  }
}

function getDayState(rep, dateKey, now) {
  if (!isScheduledWorkday(defaultHoursFor(rep.companyId, dateKey).workingDays, dateKey)) {
    return unscheduledDayState(rep, dateKey, 'rest-day')
  }
  const leave = getApprovedLeave(rep.employeeId, dateKey)
  if (leave) return unscheduledDayState(rep, dateKey, 'on-leave', leave)

  const shift = workHoursFor(rep, dateKey)
  const rng = rngFor('attendance', rep.employeeId, dateKey)
  const isToday = dateKey === todayKey(now)

  const checkedIn = rng() < 0.92
  let checkInTime = null
  let checkOutTime = null
  if (checkedIn) {
    const startMin = shift.startMinutes
    const inMinute = Math.floor(startMin - 15 + rng() * 35)
    checkInTime = minutesToIso(dateKey, inMinute)
    const endMin = shift.endMinutes
    const outMinute = Math.floor(endMin + rng() * 25)
    const outIso = minutesToIso(dateKey, outMinute)
    // A check-out only exists if it is in the past.
    if (!isToday || new Date(outIso).getTime() < now.getTime()) {
      if (rng() < 0.85) checkOutTime = outIso
    }
  }

  const events = generateDayEvents(rep, dateKey, now)
  const completed = events.filter((e) =>
    ['verified', 'failed-face', 'outside-shop', 'gps-unavailable'].includes(e.result),
  )
  const missed = events.filter((e) => e.result === 'missed')
  const failed = events.filter((e) =>
    ['failed-face', 'outside-shop'].includes(e.result),
  )

  let status
  if (!checkedIn) status = 'not-checked-in'
  else if (checkOutTime) status = 'checked-out'
  else if (events.length === 0) status = 'awaiting-verification'
  else {
    const latest = events[events.length - 1]
    if (latest.result === 'verified') status = 'on-duty-verified'
    else if (latest.result === 'missed') status = 'verification-missed'
    else if (latest.result === 'failed-face') status = 'face-verification-failed'
    else if (latest.result === 'outside-shop') status = 'location-exception'
    else status = 'awaiting-verification'
  }

  return {
    rep,
    date: dateKey,
    checkedIn,
    checkInTime,
    checkOutTime,
    events,
    completedCount: completed.length,
    missedCount: missed.length,
    failedCount: failed.length,
    progress: `${completed.length}/${VERIFICATIONS_PER_SHIFT}`,
    status,
    lastVerification: events.length ? events[events.length - 1] : null,
  }
}

/* --------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------ */

function todayKey(date = new Date()) {
  const y = date.getFullYear()
  const m = String(date.getMonth() + 1).padStart(2, '0')
  const d = String(date.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

/**
 * MOCK ONLY — monitoring overview for a company on a date.
 * @returns {{ reps: object[], stats: object }}
 */
export function mockGetMonitoringOverview({ companyId, date }) {
  const now = new Date()
  const dateKey = date ?? todayKey(now)
  const reps = mockListSalesReps(companyId).map((rep) => {
    const day = getDayState(rep, dateKey, now)
    return {
      ...rep,
      companyName: getCompanyById(rep.companyId)?.name ?? '',
      shop: mockGetShop(rep.assignedShopId),
      shift: workHoursFor(rep, dateKey),
      day,
    }
  })

  const stats = {
    total: reps.length,
    verifiedOnDuty: reps.filter((r) => r.day.status === 'on-duty-verified').length,
    awaiting: reps.filter((r) => r.day.status === 'awaiting-verification').length,
    missedChecks: reps.reduce((sum, r) => sum + r.day.missedCount, 0),
    locationExceptions: reps.reduce(
      (sum, r) =>
        sum + r.day.events.filter((e) => e.result === 'outside-shop').length,
      0,
    ),
    faceFailures: reps.reduce(
      (sum, r) =>
        sum + r.day.events.filter((e) => e.result === 'failed-face').length,
      0,
    ),
  }

  return { reps, stats }
}

/**
 * MOCK ONLY — full monitoring profile for one representative on a date.
 */
export function mockGetRepresentativeDetail(employeeId, date) {
  const rep = mockGetSalesRep(employeeId)
  if (!rep) return null
  const now = new Date()
  const dateKey = date ?? todayKey(now)
  const day = getDayState(rep, dateKey, now)
  return {
    ...rep,
    companyName: getCompanyById(rep.companyId)?.name ?? '',
    shop: mockGetShop(rep.assignedShopId),
    shift: workHoursFor(rep, dateKey),
    day,
  }
}

/* --------------------------------------------------------------------------
 * Alerts and exceptions
 * ------------------------------------------------------------------------ */

const ALERT_META = {
  'missed-verification': { label: 'Missed SMS verification', severity: 'medium' },
  'failed-face': { label: 'Failed face verification', severity: 'high' },
  'outside-shop': { label: 'Outside assigned shop radius', severity: 'high' },
  'gps-unavailable': { label: 'GPS unavailable', severity: 'low' },
  'sms-failed': { label: 'SMS delivery failure', severity: 'medium' },
  'repeated-failures': { label: 'Repeated verification failures', severity: 'high' },
  'not-checked-in': { label: 'Employee not checked in', severity: 'medium' },
  'incomplete-verification': { label: 'Incomplete attendance verification', severity: 'low' },
}

/**
 * MOCK ONLY — alerts for a company on a date, newest first.
 * Alerts are derived from the day's records; HR review state persists.
 * NOTE: a missed SMS never marks anyone absent automatically. Every alert
 * requires management review.
 */
export function mockGetAlerts({ companyId, date }) {
  const now = new Date()
  const dateKey = date ?? todayKey(now)
  const isToday = dateKey === todayKey(now)
  const overrides = readJson(ALERT_STATE_KEY, {})
  const alerts = []

  mockListSalesReps(companyId).forEach((rep) => {
    const day = getDayState(rep, dateKey, now)
    // Rest days, holidays and approved leave are not exceptions.
    if (day.status === 'rest-day' || day.status === 'on-leave') return
    const shop = mockGetShop(rep.assignedShopId)
    const shift = workHoursFor(rep, dateKey)

    const push = (type, eventId, createdAt) => {
      const exceptionId = `${rep.employeeId}:${dateKey}:${type}:${eventId ?? 'day'}`
      const override = overrides[exceptionId] ?? {}
      alerts.push({
        exceptionId,
        employeeId: rep.employeeId,
        employeeName: rep.fullName,
        shopName: shop?.shopName ?? '',
        eventId: eventId ?? null,
        type,
        typeLabel: ALERT_META[type].label,
        severity: ALERT_META[type].severity,
        status: override.status ?? 'new',
        resolutionNote: override.resolutionNote ?? '',
        createdAt,
      })
    }

    // Not checked in (only once the shift has started).
    const shiftStartIso = minutesToIso(dateKey, shift.startMinutes)
    if (!day.checkedIn && (!isToday || now.getTime() >= new Date(shiftStartIso).getTime())) {
      push('not-checked-in', null, shiftStartIso)
    }

    day.events.forEach((event) => {
      if (event.result === 'missed') push('missed-verification', event.eventId, event.dispatchedAt)
      if (event.result === 'failed-face') push('failed-face', event.eventId, event.respondedAt ?? event.dispatchedAt)
      if (event.result === 'outside-shop') push('outside-shop', event.eventId, event.respondedAt ?? event.dispatchedAt)
      if (event.result === 'gps-unavailable') push('gps-unavailable', event.eventId, event.respondedAt ?? event.dispatchedAt)
      if (event.result === 'sms-failed') push('sms-failed', event.eventId, event.dispatchedAt)
    })

    // Repeated failures: 2 or more missed/failed checks in the day.
    if (day.missedCount + day.failedCount >= monitoringSettings().repeatedExceptionThreshold) {
      const last = day.events[day.events.length - 1]
      if (last) push('repeated-failures', null, last.respondedAt ?? last.dispatchedAt)
    }

    // Incomplete verification once the shift has ended.
    const shiftEndIso = minutesToIso(dateKey, shift.endMinutes)
    const shiftEnded = !isToday || now.getTime() >= new Date(shiftEndIso).getTime()
    if (day.checkedIn && shiftEnded && day.completedCount < VERIFICATIONS_PER_SHIFT) {
      push('incomplete-verification', null, shiftEndIso)
    }
  })

  return alerts.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
}

/**
 * MOCK ONLY — record an HR review decision on an alert.
 * @returns {object|null} the updated alert state.
 */
export function mockUpdateAlert(exceptionId, { status, resolutionNote }, { audit = true } = {}) {
  const overrides = readJson(ALERT_STATE_KEY, {})
  const previous = overrides[exceptionId]?.status ?? 'new'
  overrides[exceptionId] = {
    status,
    resolutionNote: resolutionNote ?? '',
    reviewedAt: new Date().toISOString(),
  }
  writeJson(ALERT_STATE_KEY, overrides)
  // Reviews made here are audited. Reviews pushed from Notifications are
  // audited there (audit: false) so the same action is not logged twice.
  if (audit) {
    const [employeeId, dateKey, type] = exceptionId.split(':')
    const rep = mockGetSalesRep(employeeId)
    const u = getSessionUser()
    recordAuditEvent({
      action: status === 'resolved' ? 'Monitoring alert resolved' : 'Monitoring alert review updated',
      category: 'Merchandiser Monitoring',
      source: 'Merchandiser Monitoring',
      actor: u ? { name: u.name, role: u.role } : { name: 'System', role: 'System' },
      companyIds: rep ? [rep.companyId] : [],
      affected: `${rep?.fullName ?? employeeId} (${employeeId}) · ${dateKey} · ${ALERT_META[type]?.label ?? type}`,
      description: resolutionNote || '',
      previous: { status: previous },
      next: { status },
    })
  }
  return overrides[exceptionId]
}

/**
 * MOCK ONLY — the saved HR review state of one alert, or null. Lets the
 * Notifications module keep its review status in step with this module.
 */
export function mockGetAlertReview(exceptionId) {
  return readJson(ALERT_STATE_KEY, {})[exceptionId] ?? null
}

/* --------------------------------------------------------------------------
 * Live field board — real recorded data only
 *
 * The system never tracks reps continuously. It knows a rep's position only
 * at the moments a verification check was answered, and stores the distance
 * from the assigned shop (not coordinates). The board therefore shows each
 * rep AT THEIR SHOP with the result of their latest recorded check. Between
 * checks the location is unknown, and future check times are never shown.
 * ------------------------------------------------------------------------ */

export const FIELD_STATE = {
  inside: { label: 'Inside geofence at last check', short: 'Inside geofence', tone: 'ok' },
  outside: { label: 'Outside geofence at last check', short: 'Outside geofence', tone: 'crit' },
  'face-failed': { label: 'Face check failed at last check', short: 'Face check failed', tone: 'crit' },
  'location-unknown': { label: 'Location unavailable at last check', short: 'Location unavailable', tone: 'warn' },
  'no-response': { label: 'No response to last check', short: 'No response', tone: 'warn' },
  'awaiting-check': { label: 'On duty — no check yet today', short: 'Awaiting first check', tone: 'pending' },
  'checked-out': { label: 'Checked out for the day', short: 'Checked out', tone: 'muted' },
  'not-checked-in': { label: 'Not checked in (shift has started)', short: 'Not checked in', tone: 'warn' },
  'before-shift': { label: 'Shift not started yet', short: 'Shift not started', tone: 'muted' },
  'off-schedule': { label: 'Not scheduled today (rest day or leave)', short: 'Not scheduled', tone: 'muted' },
  'no-data': { label: 'No verification data for this employee', short: 'No verification data', tone: 'muted' },
}

function liveState(day, shift, dateKey, now) {
  if (day.status === 'rest-day' || day.status === 'on-leave') return 'off-schedule'
  const startMs = new Date(minutesToIso(dateKey, shift.startMinutes)).getTime()
  if (!day.checkedIn) return now.getTime() < startMs ? 'before-shift' : 'not-checked-in'
  if (day.checkOutTime) return 'checked-out'
  const last = day.events[day.events.length - 1]
  if (!last) return 'awaiting-check'
  return {
    verified: 'inside',
    'outside-shop': 'outside',
    'failed-face': 'face-failed',
    'gps-unavailable': 'location-unknown',
    missed: 'no-response',
    'sms-failed': 'no-response',
  }[last.result] ?? 'awaiting-check'
}

/**
 * MOCK ONLY — the live field board for a company, as of now.
 * @returns {{ asOf: string, reps: object[], counts: object, shops: object[] }}
 */
export function mockGetLiveFieldBoard(companyId) {
  const now = new Date()
  const dateKey = todayKey(now)
  const nowIso = now.toISOString()
  const monitored = mockListSalesReps(companyId).map((rep) => {
    const day = getDayState(rep, dateKey, now)
    const shift = workHoursFor(rep, dateKey)
    const shop = mockGetShop(rep.assignedShopId)
    // Only events that have already happened (generateDayEvents guarantees it;
    // filtered again here so a future time can never reach the screen).
    const events = day.events.filter((e) => e.dispatchedAt <= nowIso)
    const last = events[events.length - 1] ?? null
    const lastGps = [...events].reverse().find((e) => e.distanceFromShop != null) ?? null
    const lastAt = last ? last.respondedAt ?? last.dispatchedAt : null
    return {
      employeeId: rep.employeeId,
      fullName: rep.fullName,
      phoneNumber: rep.phoneNumber,
      position: rep.position,
      shop,
      shift,
      state: liveState({ ...day, events }, shift, dateKey, now),
      checkInTime: day.checkInTime,
      checkOutTime: day.checkOutTime,
      checksDone: events.length,
      lastCheck: last,
      lastCheckAt: lastAt,
      minutesSinceLastCheck: lastAt ? Math.max(0, Math.round((now.getTime() - Date.parse(lastAt)) / 60000)) : null,
      lastDistance: lastGps?.distanceFromShop ?? null,
      lastAccuracy: lastGps?.gpsAccuracy ?? null,
      lastGpsAt: lastGps ? lastGps.respondedAt ?? lastGps.dispatchedAt : null,
      hasData: true,
    }
  })
  const ids = new Set(monitored.map((r) => r.employeeId))
  const registered = mockListFieldStaff(companyId)
    .filter((r) => r.noSmsData && !ids.has(r.employeeId))
    .map((r) => ({
      employeeId: r.employeeId,
      fullName: r.fullName,
      phoneNumber: r.phoneNumber,
      position: r.position,
      shop: r.assignedShopId ? mockGetShop(r.assignedShopId) : null,
      shift: null,
      state: 'no-data',
      checksDone: 0,
      lastCheck: null,
      lastCheckAt: null,
      minutesSinceLastCheck: null,
      lastDistance: null,
      lastAccuracy: null,
      hasData: false,
    }))
  const reps = [...monitored, ...registered].sort((a, b) => a.fullName.localeCompare(b.fullName))
  const counts = Object.fromEntries(Object.keys(FIELD_STATE).map((k) => [k, reps.filter((r) => r.state === k).length]))
  counts.onDuty = reps.filter((r) => ['inside', 'outside', 'face-failed', 'location-unknown', 'no-response', 'awaiting-check'].includes(r.state)).length
  return { asOf: nowIso, dateKey, reps, counts, shops: mockListShops(companyId) }
}
